"""Summarize frozen candidates and all failures without selecting on evaluation."""
import json
from pathlib import Path
import pandas as pd
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from research.return_search.run import OUT


def main():
    dev=json.loads((OUT/'dev/results.json').read_text());evaluation=json.loads((OUT/'evaluation/results.json').read_text())
    secondary=json.loads((OUT/'secondary_evaluation/results.json').read_text());diag=json.loads((OUT/'diagnostics/results.json').read_text());long=json.loads((OUT/'diagnostics/long_record.json').read_text());sel=json.loads((OUT/'selection.json').read_text())
    lines=['# Broad return search: completed results, 19 September 2026','','**Strongest return candidate: long-only stock momentum.** It returned 36.22% annually with 1.00 excess Sharpe in the continuous 2019–September 2026 record. The longer 2008–2026 extension returned 22.52% with 0.80 Sharpe and a 57.64% maximum drawdown. The stock universe consists of current listed names, so survivorship remains an unresolved limitation. These are simulated results, not a claim of a proven new anomaly.','','The higher recent Sharpe candidate was cross-asset ETF momentum: 1.51 Sharpe and 59.85% annualized return in July 2025–September 2026. Its full 2008–2026 history was much weaker: 5.61% return and 0.31 Sharpe. The recent number must not be substituted for that longer record.','','## What was tested','','Twenty fixed candidates, four passive controls. No parameter grid or evaluation-period retuning. Seven stock candidates, seven ETF candidates, four BTC/ETH candidates and two volatility-product candidates. Learned models used annual expanding-window training, matured-label purges, and fixed ridge/gradient-boosting hyperparameters. Training included up to 175,625 earlier stock observations per annual fit. Price, volume and volatility fields were tested; enriched models also used options-volume fields for the 46 available underlyings, VIX structure, yield slope and credit/market trends. More features and learning did not beat the simple stock-momentum rule in the selection period.','','The LSE Terminal MCP connection and data catalog were checked and saved. Historical options data came from the LSE vault. Official-session adjusted equity/ETF prices and continuous crypto aggregate daily prices came from the project cache. No demo/synthetic prices or broker execution were used. Revised macro data and insufficient insider history were excluded. Prior COT, FX, intraday and option-writing studies remain separate recorded trials; this run does not claim to test every conceivable market or field.','','## Exact candidate rules','','**Stock momentum**','','1. On the first trading session close of each month, retain stocks with at least 252 sessions of history and finite price features.','2. Require trailing 63-session average dollar volume above $20 million and rank within the top 200 by that liquidity measure.','3. Score each stock as adjusted close 21 sessions ago divided by adjusted close 252 sessions ago, minus one. This skips the latest month.','4. Buy up to 20 positive-score leaders at 5% target weight each. Unused slots stay in cash.','5. Execute at the next session open, hold actual share units between monthly decisions, and mark positions daily. No shorts or leverage.','','**ETF momentum** uses the same skipped-month score across the fixed cached ETF universe, selecting up to four positive leaders at 25% each. It covers international and US equities, bonds, credit, real estate, commodities and currencies.','','## Chronology and selection','','- Annual prediction and selection window: 2019-01-01 through 2025-06-30. Each model was fitted only to labels that ended before its prediction year.','- A selection file was written before evaluation. Stock momentum and ETF momentum were the selected winners in their respective families.','- The originally selected overall candidate subject to the preset risk limits was crypto breakout. **It failed evaluation**. The report does not retroactively replace that primary with the better-looking ETF result.','- Before evaluation, a documented reporting extension also froze the highest-returning strategy and highest-returning fitted model, without the risk limits. Both were crypto candidates. They failed to reproduce their earlier returns.','- Evaluation: 2025-07-01 to 2026-09-17, approximately 14.6 months. These dates were withheld from this selection process, but the wider project had previously used some of this history.','- Continuous 2019–2026 results, the backward 2008–2018 extension, execution-delay tests and asset-omission tests are post-evaluation diagnostics. They are not new model-selection opportunities or pristine holdouts.','','## Final-period evaluation','','Annualized return can look large over 14.6 months; total return is shown alongside it.','','| Frozen candidate / control | Net total return | Net annualized return | Excess Sharpe | Max DD | Stress annualized return |','|---|---:|---:|---:|---:|---:|']
    combined={**evaluation,**secondary}
    for key in ['stocks__momentum','etf__momentum','fixed_blend','crypto__breakout','crypto__trend','crypto__ridge_price','crypto__passive','etf__passive','vol__passive']:
        b=combined[key]['base'];s=combined[key]['stress']
        lines.append(f"| {key} | {b['total_return']:.2%} | {b['cagr']:.2%} | {b['excess_sharpe']:.2f} | {b['max_dd']:.2%} | {s['cagr']:.2%} |")
    lines += ['','SPY and QQQ passive controls over the same final period earned 20.16% and 24.85% annualized respectively. Their excess Sharpes were 1.25 and 1.09.','','## Longer descriptive record','','| Strategy | Window | Net CAGR | Excess Sharpe | Max DD |','|---|---|---:|---:|---:|']
    for family in ['stocks','etf']:
        key=family+'__momentum'
        for window,b in [('2019–2026',diag[key]['continuous_base']),('2008–2026',long[key]['base'])]:
            lines.append(f"| {key} | {window} | {b['cagr']:.2%} | {b['excess_sharpe']:.2f} | {b['max_dd']:.2%} |")
    for key in ['SPY','QQQ']:
        b=long[key];lines.append(f"| {key} passive | 2008–2026 | {b['cagr']:.2%} | {b['excess_sharpe']:.2f} | {b['max_dd']:.2%} |")
    lines += ['','## Execution and robustness','','All reported portfolio returns mark open positions daily and include final liquidation. Stock/ETF base costs are 5bps per side, stressed to 15bps. Crypto costs are 20bps per side, stressed to 50bps, with an extra full intervening day before execution. Volatility ETF costs are 10bps per side, stressed to 30bps. All portfolios are fully funded, so no short borrow or debit financing is needed. Cash earns the prior observable IRX rate over elapsed days. Adjusted fund returns include distributions and embedded fund expenses. Taxes, account-specific fees, capacity and measured broker fills are not established by this simulation.','','A full extra session of delay plus tripled stock/ETF costs left stock momentum at 66.39% annualized return / 1.24 Sharpe in evaluation, and ETF momentum at 57.67% / 1.47. This reduces concern that the results rely on an exact next-open fill. It does not establish realized execution quality.','','Removing one at a time the three most frequently allocated stocks left evaluation CAGR between 62.47% and 66.76%. Removing the equivalent ETFs left 39.94% to 51.55%. Removed slots stayed cash; no weights were reoptimized. The leading average ETF allocations were silver, South Korea equities and gold, so this remains materially dependent on the recent asset regime.','','Seven focused tests passed: funded accounting and fees, full-day crypto delay, missing held-price failure, cash-slot sizing, initial-loss drawdowns, causal features under future perturbation, and annual training-label purges.','','## What remains unproven','','The stock list is current-member and survivor biased. Historical holdings were chosen from past prices and liquidity, but the database lacks the full historical investable universe with delisted names. That prevents calling the stock result a clean point-in-time validation. The 2008–2026 stock drawdown is 57.64%, substantially deeper than the selection-window drawdown.','','The final evaluation is short. Twenty-session block bootstraps give wide uncertainty intervals, and alpha confidence intervals against SPY and QQQ include zero for both momentum candidates. The strongest conclusions are that these are reproducible higher-return candidates and their recent results survive modeled cost/delay stress—not that a durable undiscovered alpha has been statistically established. Project-wide multiple testing is not erased by this run.','','The stock passive control stopped on a missing FISV open/close for 2025-11-12. A fresh Yahoo query confirmed the absent bar. No price was invented or forward-filled in execution. The selected stock strategy had no exposure to that missing bar and completed normally. SPY and QQQ provide complete additional passive comparisons.','','## Full earlier-period trial ledger','','| Candidate / control | 2019–June 2025 net CAGR | Excess Sharpe | Max DD | Stress CAGR |','|---|---:|---:|---:|---:|']
    for k,v in sorted(dev.items(),key=lambda item:item[1]['base']['cagr'],reverse=True):
        b=v['base'];s=v['stress'];lines.append(f"| {k} | {b['cagr']:.2%} | {b['excess_sharpe']:.2f} | {b['max_dd']:.2%} | {s['cagr']:.2%} |")
    lines += ['','## Artifacts','','- [Original protocol](../../research/return_search/PLAN.md)','- [Frozen selection](selection.json)','- [Return-leader reporting extension](../../research/return_search/EVALUATION_EXTENSION.md)','- [Final evaluation](evaluation/results.json)','- [Return-leader evaluation](secondary_evaluation/results.json)','- [Execution and concentration diagnostics](diagnostics/results.json)','- [Full historical extension](diagnostics/long_record.json)','- [Frozen paper-research specifications](paper_candidates.json)','','Daily NAV, targets, costs, data fingerprints and training audits are saved beside these reports. No live strategy or account was changed.']
    (OUT/'REPORT.md').write_text('\n'.join(lines)+'\n')
    candidates={k:{'status':'research candidate; not live','signal':'positive 12-1 momentum','decision':'first trading session close monthly','fill':'next trading session open','gross_cap':1,'target_slots':20 if k.startswith('stocks') else 4,'stock_liquidity_rule':'63-session ADV > $20m; top 200' if k.startswith('stocks') else None,'latest_observed_signal_date':diag[k]['latest_target_date'],'latest_research_targets':diag[k]['latest_research_targets'],'selection_source':'2019-01-01 through 2025-06-30','source_code_sha256':sel['code_sha256']} for k in ['stocks__momentum','etf__momentum']}
    (OUT/'paper_candidates.json').write_text(json.dumps(candidates,indent=2))
    fig,axes=plt.subplots(2,1,figsize=(12,8),sharex=True,gridspec_kw={'height_ratios':[2,1]})
    for label,file,color in [('Stock momentum','stocks__momentum_2008_base.csv','#007a78'),('ETF momentum','etf__momentum_2008_base.csv','#c35e2b'),('SPY','SPY_2008.csv','#7b8493'),('QQQ','QQQ_2008.csv','#6958ab')]:
        f=pd.read_csv(OUT/'diagnostics'/file,index_col=0,parse_dates=True);nav=(1+f['return']).cumprod()
        axes[0].plot(nav.index,nav,label=label,color=color,lw=1.6)
        dd=nav/nav.cummax().clip(lower=1)-1;axes[1].plot(dd.index,dd*100,color=color,lw=1)
    axes[0].set_yscale('log');axes[0].set_ylabel('Growth of $1 (log scale)');axes[0].legend(ncol=4,loc='upper left');axes[0].set_title('Fixed monthly momentum rules: net simulated performance, 2008–2026',loc='left',fontweight='bold')
    axes[1].set_ylabel('Drawdown (%)')
    for ax in axes:
        ax.grid(alpha=.2);ax.axvline(pd.Timestamp('2025-07-01'),color='black',ls='--',alpha=.4)
    fig.text(.08,.015,'Descriptive full history; selection used 2019–June 2025. Stock universe has survivorship bias. Costs included; no leverage.',fontsize=9)
    fig.tight_layout(rect=(0,.04,1,1));fig.savefig(OUT/'equity_and_drawdown.png',dpi=160);plt.close(fig)
    print(OUT/'REPORT.md')
if __name__=='__main__':main()
